INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (243, NULL, NULL, 2, '[\"文学\"]', '[{\"author\":\"加西亚·马尔克斯\",\"bookId\":1,\"bookName\":\"《百年孤独》\",\"digest\":\"一部魔幻现实主义巨著，讲述了布恩迪亚家族七代人的传奇故事。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=百年孤独\",\"subject\":\"文学\"},{\"author\":\"鲁迅\",\"bookId\":2,\"bookName\":\"《呐喊》\",\"digest\":\"收录鲁迅从1918年至1922年所作的14部短篇小说，揭示了种种深层次的社会矛盾。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=呐喊\",\"subject\":\"文学\"},{\"author\":\"莎士比亚\",\"bookId\":3,\"bookName\":\"《哈姆雷特》\",\"digest\":\"讲述了哈姆雷特为父王向叔叔复仇的故事，探讨了人性、道德等诸多问题。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=哈姆雷特\",\"subject\":\"文学\"},{\"author\":\"欧内斯特·海明威\",\"bookId\":4,\"bookName\":\"《老人与海》\",\"digest\":\"故事围绕一位老年古巴渔夫，与一条巨大的马林鱼在离岸很远的湾流中的搏斗展开。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=老人与海\",\"subject\":\"文学\"},{\"author\":\"夏洛蒂·勃朗特\",\"bookId\":5,\"bookName\":\"《简·爱》\",\"digest\":\"讲述了一个自幼父母双亡的孤女简·爱，不断追求自由与尊严、坚持自我并最终获得幸福的故事。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=简·爱\",\"subject\":\"文学\"},{\"author\":\"维克多·雨果\",\"bookId\":6,\"bookName\":\"《巴黎圣母院》\",\"digest\":\"以离奇和对比手法写了一个发生在15世纪法国的故事，反映了专制社会的黑暗、宗教的虚伪等。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=巴黎圣母院\",\"subject\":\"文学\"},{\"author\":\"玛格丽特·米切尔\",\"bookId\":7,\"bookName\":\"《飘》\",\"digest\":\"以美国南北战争为背景，讲述了南方种植园主家庭的女儿斯嘉丽在乱世中的成长历程。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=飘\",\"subject\":\"文学\"},{\"author\":\"罗贯中\",\"bookId\":8,\"bookName\":\"《三国演义》\",\"digest\":\"描写了从东汉末年到西晋初年之间近百年的历史风云，诉说了东汉末年的群雄割据混战和魏、蜀、吴三国之间的政治和军事斗争。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=三国演义\",\"subject\":\"文学\"},{\"author\":\"曹雪芹\",\"bookId\":9,\"bookName\":\"《红楼梦》\",\"digest\":\"以贾、史、王、薛四大家族的兴衰为背景，以贾宝玉与林黛玉、薛宝钗的爱情婚姻悲剧为主线，从多个角度描写了18世纪上半叶中国封建社会的生活百态。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=红楼梦\",\"subject\":\"文学\"},{\"author\":\"老舍\",\"bookId\":10,\"bookName\":\"《骆驼祥子》\",\"digest\":\"讲述了20世纪20年代军阀混战时期人力车夫祥子三起三落的人生经历，揭示了半殖民地半封建社会的黑暗。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=骆驼祥子\",\"subject\":\"文学\"}]', '2025-04-02 15:35:17');
INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (244, NULL, NULL, 2, '[\"法学\"]', '[{\"author\":\"孟德斯鸠\",\"bookId\":11,\"bookName\":\"《论法的精神》\",\"digest\":\"探讨了法的精神与政治、法律制度的关系，提出了三权分立学说。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=论法的精神\",\"subject\":\"法学\"},{\"author\":\"博登海默\",\"bookId\":12,\"bookName\":\"《法理学：法律哲学与法律方法》\",\"digest\":\"全面阐述了法理学的基本问题和法律哲学的主要流派。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=法理学\",\"subject\":\"法学\"},{\"author\":\"张千帆\",\"bookId\":13,\"bookName\":\"《宪法学》\",\"digest\":\"系统介绍了宪法学的基本原理、中国宪法的历史发展和主要内容等。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=宪法学\",\"subject\":\"法学\"},{\"author\":\"王利明\",\"bookId\":14,\"bookName\":\"《民法总则研究》\",\"digest\":\"对民法总则的各项制度和规则进行了深入研究和探讨。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=民法总则研究\",\"subject\":\"法学\"},{\"author\":\"张明楷\",\"bookId\":15,\"bookName\":\"《刑法学》\",\"digest\":\"详细讲解了刑法的基本理论、犯罪构成、刑罚制度等内容。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=刑法学\",\"subject\":\"法学\"},{\"author\":\"姜明安\",\"bookId\":16,\"bookName\":\"《行政法与行政诉讼法》\",\"digest\":\"介绍了行政法的基本概念、原则、行政行为以及行政诉讼等方面的知识。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=行政法与行政诉讼法\",\"subject\":\"法学\"},{\"author\":\"崔建远\",\"bookId\":17,\"bookName\":\"《合同法》\",\"digest\":\"围绕合同的订立、效力、履行、变更、转让等方面进行了详细阐述。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=合同法\",\"subject\":\"法学\"},{\"author\":\"吴汉东\",\"bookId\":18,\"bookName\":\"《知识产权法》\",\"digest\":\"阐述了知识产权的基本原理、著作权、专利权、商标权等相关法律制度。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=知识产权法\",\"subject\":\"法学\"},{\"author\":\"王铁崖\",\"bookId\":19,\"bookName\":\"《国际法》\",\"digest\":\"介绍了国际法的基本概念、原则、主体、领土、海洋法等内容。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=国际法\",\"subject\":\"法学\"},{\"author\":\"何家弘\",\"bookId\":20,\"bookName\":\"《证据法学》\",\"digest\":\"对证据法的基本理论、证据规则、证明责任等进行了系统研究。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=证据法学\",\"subject\":\"法学\"}]', '2025-04-02 15:35:35');
INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (245, NULL, NULL, 2, '[\"文学\"]', '[{\"author\":\"加西亚·马尔克斯\",\"bookId\":1,\"bookName\":\"《百年孤独》\",\"digest\":\"一部魔幻现实主义巨著，讲述了布恩迪亚家族七代人的传奇故事。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=百年孤独\",\"subject\":\"文学\"},{\"author\":\"鲁迅\",\"bookId\":2,\"bookName\":\"《呐喊》\",\"digest\":\"收录鲁迅从1918年至1922年所作的14部短篇小说，揭示了种种深层次的社会矛盾。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=呐喊\",\"subject\":\"文学\"},{\"author\":\"莎士比亚\",\"bookId\":3,\"bookName\":\"《哈姆雷特》\",\"digest\":\"讲述了哈姆雷特为父王向叔叔复仇的故事，探讨了人性、道德等诸多问题。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=哈姆雷特\",\"subject\":\"文学\"},{\"author\":\"欧内斯特·海明威\",\"bookId\":4,\"bookName\":\"《老人与海》\",\"digest\":\"故事围绕一位老年古巴渔夫，与一条巨大的马林鱼在离岸很远的湾流中的搏斗展开。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=老人与海\",\"subject\":\"文学\"},{\"author\":\"夏洛蒂·勃朗特\",\"bookId\":5,\"bookName\":\"《简·爱》\",\"digest\":\"讲述了一个自幼父母双亡的孤女简·爱，不断追求自由与尊严、坚持自我并最终获得幸福的故事。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=简·爱\",\"subject\":\"文学\"},{\"author\":\"维克多·雨果\",\"bookId\":6,\"bookName\":\"《巴黎圣母院》\",\"digest\":\"以离奇和对比手法写了一个发生在15世纪法国的故事，反映了专制社会的黑暗、宗教的虚伪等。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=巴黎圣母院\",\"subject\":\"文学\"},{\"author\":\"玛格丽特·米切尔\",\"bookId\":7,\"bookName\":\"《飘》\",\"digest\":\"以美国南北战争为背景，讲述了南方种植园主家庭的女儿斯嘉丽在乱世中的成长历程。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=飘\",\"subject\":\"文学\"},{\"author\":\"罗贯中\",\"bookId\":8,\"bookName\":\"《三国演义》\",\"digest\":\"描写了从东汉末年到西晋初年之间近百年的历史风云，诉说了东汉末年的群雄割据混战和魏、蜀、吴三国之间的政治和军事斗争。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=三国演义\",\"subject\":\"文学\"},{\"author\":\"曹雪芹\",\"bookId\":9,\"bookName\":\"《红楼梦》\",\"digest\":\"以贾、史、王、薛四大家族的兴衰为背景，以贾宝玉与林黛玉、薛宝钗的爱情婚姻悲剧为主线，从多个角度描写了18世纪上半叶中国封建社会的生活百态。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=红楼梦\",\"subject\":\"文学\"},{\"author\":\"老舍\",\"bookId\":10,\"bookName\":\"《骆驼祥子》\",\"digest\":\"讲述了20世纪20年代军阀混战时期人力车夫祥子三起三落的人生经历，揭示了半殖民地半封建社会的黑暗。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=骆驼祥子\",\"subject\":\"文学\"}]', '2025-04-02 15:35:42');
