林黛玉、薛宝钗的爱情婚姻悲剧为主线，从多个角度描写了18世纪上半叶中国封建社会的生活百态。\",\"picture\":\"https://cdn.pixabay.com/photo/2015/06/02/12/59/book-794978_1280.jpg\",\"subject\":\"文学\"},{\"author\":\"老舍\",\"bookId\":10,\"bookName\":\"《骆驼祥子》\",\"digest\":\"讲述了20世纪20年代军阀混战时期人力车夫祥子三起三落的人生经历，揭示了半殖民地半封建社会的黑暗。\",\"picture\":\"https://cdn.pixabay.com/photo/2018/07/01/20/01/music-3510326_1280.jpg\",\"subject\":\"文学\"}]', '2025-04-02 15:43:40');
INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (247, NULL, NULL, 2, '[\"法学\"]', '[{\"author\":\"孟德斯鸠\",\"bookId\":11,\"bookName\":\"《论法的精神》\",\"digest\":\"探讨了法的精神与政治、法律制度的关系，提出了三权分立学说。\",\"picture\":\"https://cdn.pixabay.com/photo/2023/10/05/11/57/book-8295812_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"博登海默\",\"bookId\":12,\"bookName\":\"《法理学：法律哲学与法律方法》\",\"digest\":\"全面阐述了法理学的基本问题和法律哲学的主要流派。\",\"picture\":\"https://cdn.pixabay.com/photo/2018/10/04/14/22/reading-3723751_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"张千帆\",\"bookId\":13,\"bookName\":\"《宪法学》\",\"digest\":\"系统介绍了宪法学的基本原理、中国宪法的历史发展和主要内容等。\",\"picture\":\"https://cdn.pixabay.com/photo/2022/11/08/06/05/read-7577787_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"王利明\",\"bookId\":14,\"bookName\":\"《民法总则研究》\",\"digest\":\"对民法总则的各项制度和规则进行了深入研究和探讨。\",\"picture\":\"https://cdn.pixabay.com/photo/2015/12/05/08/25/fantasy-1077863_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"张明楷\",\"bookId\":15,\"bookName\":\"《刑法学》\",\"digest\":\"详细讲解了刑法的基本理论、犯罪构成、刑罚制度等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2022/11/03/13/07/book-7567437_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"姜明安\",\"bookId\":16,\"bookName\":\"《行政法与行政诉讼法》\",\"digest\":\"介绍了行政法的基本概念、原则、行政行为以及行政诉讼等方面的知识。\",\"picture\":\"https://cdn.pixabay.com/photo/2023/01/15/16/20/library-7720589_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"崔建远\",\"bookId\":17,\"bookName\":\"《合同法》\",\"digest\":\"围绕合同的订立、效力、履行、变更、转让等方面进行了详细阐述。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/29/07/21/book-1868068_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"吴汉东\",\"bookId\":18,\"bookName\":\"《知识产权法》\",\"digest\":\"阐述了知识产权的基本原理、著作权、专利权、商标权等相关法律制度。\",\"picture\":\"https://cdn.pixabay.com/photo/2020/05/15/13/28/reading-5173530_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"王铁崖\",\"bookId\":19,\"bookName\":\"《国际法》\",\"digest\":\"介绍了国际法的基本概念、原则、主体、领土、海洋法等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/10/25/15/55/book-1769228_