INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (250, NULL, NULL, 2, '[\"法学\"]', '[{\"author\":\"孟德斯鸠\",\"bookId\":11,\"bookName\":\"《论法的精神》\",\"digest\":\"探讨了法的精神与政治、法律制度的关系，提出了三权分立学说。\",\"picture\":\"https://cdn.pixabay.com/photo/2023/10/05/11/57/book-8295812_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"博登海默\",\"bookId\":12,\"bookName\":\"《法理学：法律哲学与法律方法》\",\"digest\":\"全面阐述了法理学的基本问题和法律哲学的主要流派。\",\"picture\":\"https://cdn.pixabay.com/photo/2018/10/04/14/22/reading-3723751_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"张千帆\",\"bookId\":13,\"bookName\":\"《宪法学》\",\"digest\":\"系统介绍了宪法学的基本原理、中国宪法的历史发展和主要内容等。\",\"picture\":\"https://cdn.pixabay.com/photo/2022/11/08/06/05/read-7577787_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"王利明\",\"bookId\":14,\"bookName\":\"《民法总则研究》\",\"digest\":\"对民法总则的各项制度和规则进行了深入研究和探讨。\",\"picture\":\"https://cdn.pixabay.com/photo/2015/12/05/08/25/fantasy-1077863_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"张明楷\",\"bookId\":15,\"bookName\":\"《刑法学》\",\"digest\":\"详细讲解了刑法的基本理论、犯罪构成、刑罚制度等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2022/11/03/13/07/book-7567437_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"姜明安\",\"bookId\":16,\"bookName\":\"《行政法与行政诉讼法》\",\"digest\":\"介绍了行政法的基本概念、原则、行政行为以及行政诉讼等方面的知识。\",\"picture\":\"https://cdn.pixabay.com/photo/2023/01/15/16/20/library-7720589_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"崔建远\",\"bookId\":17,\"bookName\":\"《合同法》\",\"digest\":\"围绕合同的订立、效力、履行、变更、转让等方面进行了详细阐述。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/29/07/21/book-1868068_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"吴汉东\",\"bookId\":18,\"bookName\":\"《知识产权法》\",\"digest\":\"阐述了知识产权的基本原理、著作权、专利权、商标权等相关法律制度。\",\"picture\":\"https://cdn.pixabay.com/photo/2020/05/15/13/28/reading-5173530_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"王铁崖\",\"bookId\":19,\"bookName\":\"《国际法》\",\"digest\":\"介绍了国际法的基本概念、原则、主体、领土、海洋法等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/10/25/15/55/book-1769228_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"何家弘\",\"bookId\":20,\"bookName\":\"《证据法学》\",\"digest\":\"对证据法的基本理论、证据规则、证明责任等进行了系统研究。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/08/24/16/20/books-1617327_1280.jpg\",\"subject\":\"法学\"}]', '2025-04-02 15:48:44');
INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (251, NULL, NULL, 2, '[\"理学\"]', '[{\"author\":\"斯蒂芬·霍金\",\"bookId\":21,\"bookName\":\"《时间简史》\",\"digest\":\"介绍了宇宙的起源、黑洞、时间旅行等前沿科学概念。\",\"picture\":\"https://cdn.pixabay.com/photo/2019/01/30/08/30/book-3964050_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"艾萨克·牛顿\",\"bookId\":22,\"bookName\":\"《自然哲学的数学原理》\",\"digest\":\"阐述了经典力学的基本原理，是科学史上的重要著作。\",\"picture\":\"https://cdn.pixabay.com/photo/2022/03/28/18/41/spring-7098130_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"阿尔伯特·爱因斯坦\",\"bookId\":23,\"bookName\":\"《相对论》\",\"digest\":\"包含狭义相对论和广义相对论，对现代物理学产生了深远影响。\",\"picture\":\"https://cdn.pixabay.com/photo/2021/10/14/13/50/book-6709160_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"保罗·狄拉克\",\"bookId\":24,\"bookName\":\"《量子力学原理》\",\"digest\":\"是量子力学领域的经典著作，系统阐述了量子力学的基本原理和方法。\",\"picture\":\"https://cdn.pixabay.com/photo/2014/09/28/21/30/light-465350_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"华彤文\",\"bookId\":25,\"bookName\":\"《普通化学原理》\",\"digest\":\"介绍了化学的基本概念、原理和方法，涵盖了化学热力学、化学动力学等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2018/01/17/18/43/book-3088775_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"尼尔·坎贝尔\",\"bookId\":26,\"bookName\":\"《生物学导论》\",\"digest\":\"全面介绍了生物学的基本概念、生命的起源、细胞结构、遗传等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2017/01/30/10/03/book-2020460_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"宋春青\",\"bookId\":27,\"bookName\":\"《地质学基础》\",\"digest\":\"系统介绍了地质学的基本概念、地球的物质组成、地质作用等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2015/09/05/21/51/reading-925589_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"苏宜\",\"bookId\":28,\"bookName\":\"《天文学新概论》\",\"digest\":\"介绍了天文学的基本概念、天体的演化、星系的结构等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2023/03/06/14/27/man-7833615_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"华东师范大学数学系\",\"bookId\":29,\"bookName\":\"《数学分析》\",\"digest\":\"是数学专业的基础课程教材，主要内容包括极限、导数、积分等。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/29/13/46/book-1869969_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"哈里德\",\"bookId\":30,\"bookName\":\"《物理学》\",\"digest\":\"涵盖了经典物理学和现代物理学的主要内容，是一本经典的物理学教材。\",\"picture\":\"https://cdn.pixabay.com/photo/2015/11/19/21/11/atlas-1052011_1280.jpg\",\"subject\":\"理学\"}]', '2025-04-02 15:48:48');
