INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (253, NULL, NULL, 2, '[\"自然科学\"]', '[{\"author\":\"查尔斯·达尔文\",\"bookId\":41,\"bookName\":\"《物种起源》\",\"digest\":\"提出了生物进化的理论，对生物学的发展产生了深远影响。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/05/28/07/05/book-1421097_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"让 - 亨利·卡西米尔·法布尔\",\"bookId\":42,\"bookName\":\"《昆虫记》\",\"digest\":\"生动记录了昆虫的生活习性和特征，是一部优秀的科普作品。\",\"picture\":\"https://cdn.pixabay.com/photo/2022/01/22/16/54/book-6957870_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"比尔·布莱森\",\"bookId\":43,\"bookName\":\"《万物简史》\",\"digest\":\"以通俗易懂的语言介绍了宇宙、地球、生命的起源和发展等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2014/06/28/12/35/books-378903_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"斯蒂芬·霍金\",\"bookId\":44,\"bookName\":\"《果壳中的宇宙》\",\"digest\":\"继续探讨了宇宙的奥秘，包括宇宙的起源、黑洞、时间旅行等问题。\",\"picture\":\"https://cdn.pixabay.com/photo/2020/05/15/19/37/book-5174879_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"布鲁斯·阿尔伯茨\",\"bookId\":45,\"bookName\":\"《细胞》\",\"digest\":\"全面介绍了细胞的结构、功能、代谢等方面的知识。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/04/30/13/12/sutterlin-1362879_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"李扬汉\",\"bookId\":46,\"bookName\":\"《植物学》\",\"digest\":\"介绍了植物的形态、结构、分类、生理等方面的知识。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/29/11/25/bible-1869164_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"刘凌云\",\"bookId\":47,\"bookName\":\"《动物学》\",\"digest\":\"系统介绍了动物的分类、形态、生理、生态等方面的知识。\",\"picture\":\"https://cdn.pixabay.com/photo/2019/11/02/20/50/camera-4597415_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"彼得·维恩\",\"bookId\":48,\"bookName\":\"《海洋生物学》\",\"digest\":\"讲述了海洋生物的种类、生态、进化等方面的知识。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/12/30/19/33/children-1941336_1280.png\",\"subject\":\"自然科学\"},{\"author\":\"曹伯勋\",\"bookId\":49,\"bookName\":\"《地质学与地貌学》\",\"digest\":\"介绍了地球的地质构造、地质作用、地貌形成等方面的知识。\",\"picture\":\"https://cdn.pixabay.com/photo/2017/12/17/21/44/drink-3025022_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"周淑贞\",\"bookId\":50,\"bookName\":\"《气象学与气候学》\",\"digest\":\"介绍了气象学和气候学的基本概念、大气的组成和结构、天气系统和气候类型等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/23/17/31/man-1853961_1280.jpg\",\"subject\":\"自然科学\"}]', '2025-04-02 15:49:08');
INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (254, NULL, NULL, 2, '[\"工学\"]', '[{\"author\":\"唐纳德·克努特\",\"bookId\":31,\"bookName\":\"《计算机程序设计艺术》\",\"digest\":\"计算机科学领域的经典著作，涵盖了算法分析、数据结构等多个方面。\",\"picture\":\"https://cdn.pixabay.com/photo/2019/05/14/21/50/storytelling-4203628_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"机械设计手册编委会\",\"bookId\":32,\"bookName\":\"《机械设计手册》\",\"digest\":\"提供了机械设计的各种标准、规范和设计方法。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/29/02/56/blonde-1866951_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"邱关源\",\"bookId\":33,\"bookName\":\"《电路原理》\",\"digest\":\"介绍了电路的基本定律、电路分析方法、正弦稳态电路等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2017/03/23/12/23/vintage-2168174_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"胡寿松\",\"bookId\":34,\"bookName\":\"《自动控制原理》\",\"digest\":\"阐述了自动控制系统的基本原理、分析方法和设计方法。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/06/01/06/26/open-book-1428428_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"孙伟\",\"bookId\":35,\"bookName\":\"《土木工程材料》\",\"digest\":\"介绍了土木工程中常用的材料，如水泥、钢材、混凝土等的性能和应用。\",\"picture\":\"https://cdn.pixabay.com/photo/2022/07/08/10/37/books-7309019_1280.png\",\"subject\":\"工学\"},{\"author\":\"樊昌信\",\"bookId\":36,\"bookName\":\"《通信原理》\",\"digest\":\"讲述了通信系统的基本原理、模拟通信和数字通信等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2019/03/01/14/54/girl-4028008_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"谭天恩\",\"bookId\":37,\"bookName\":\"《化工原理》\",\"digest\":\"介绍了化工生产中的基本单元操作，如流体输送、传热、蒸馏等的原理和计算方法。\",\"picture\":\"https://cdn.pixabay.com/photo/2019/11/04/10/15/book-4600757_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"张海藩\",\"bookId\":38,\"bookName\":\"《软件工程》\",\"digest\":\"系统介绍了软件工程的基本概念、方法和技术，包括软件开发过程、软件项目管理等。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/18/16/56/book-1835799_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"何仰赞\",\"bookId\":39,\"bookName\":\"《电力系统分析》\",\"digest\":\"主要内容包括电力系统的潮流计算、短路计算、电力系统稳定性分析等。\",\"picture\":\"https://cdn.pixabay.com/photo/2021/12/12/09/41/woman-6864640_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"王建国\",\"bookId\":40,\"bookName\":\"《建筑设计基础》\",\"digest\":\"介绍了建筑设计的基本原理、方法和程序，培养建筑设计的基本能力。\",\"picture\":\"https://cdn.pixabay.com/photo/2019/05/04/14/22/woman-4178187_1280.jpg\",\"subject\":\"工学\"}]', '2025-04-02 15:49:10');
INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (255, NULL, NULL, 2, '[\"理学\"]', '[{\"author\":\"斯蒂芬·霍金\",\"bookId\":21,\"bookName\":\"《时间简史》\",\"digest\":\"介绍了宇宙的起源、黑洞、时间旅行等前沿科学概念。\",\"picture\":\"https://cdn.pixabay.com/photo/2019/01/30/08/30/book-3964050_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"艾萨克·牛顿\",\"bookId\":22,\"bookName\":\"《自然哲学的数学原理》\",\"digest\":\"阐述了经典力学的基本原理，是科学史上的重要著作。\",\"picture\":\"https://cdn.pixabay.com/photo/2022/03/28/18/41/spring-7098130_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"阿尔伯特·爱因斯坦\",\"bookId\":23,\"bookName\":\"《相对论》\",\"digest\":\"包含狭义相对论和广义相对论，对现代物理学产生了深远影响。\",\"picture\":\"https://cdn.pixabay.com/photo/2021/10/14/13/50/book-6709160_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"保罗·狄拉克\",\"bookId\":24,\"bookName\":\"《量子力学原理》\",\"digest\":\"是量子力学领域的经典著作，系统阐述了量子力学的基本原理和方法。\",\"picture\":\"https://cdn.pixabay.com/photo/2014/09/28/21/30/light-465350_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"华彤文\",\"bookId\":25,\"bookName\":\"《普通化学原理》\",\"digest\":\"介绍了化学的基本概念、原理和方法，涵盖了化学热力学、化学动力学等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2018/01/17/18/43/book-3088775_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"尼尔·坎贝尔\",\"bookId\":26,\"bookName\":\"《生物学导论》\",\"digest\":\"全面介绍了生物学的基本概念、生命的起源、细胞结构、遗传等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2017/01/30/10/03/book-2020460_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"宋春青\",\"bookId\":27,\"bookName\":\"《地质学基础》\",\"digest\":\"系统介绍了地质学的基本概念、地球的物质组成、地质作用等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2015/09/05/21/51/reading-925589_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"苏宜\",\"bookId\":28,\"bookName\":\"《天文学新概论》\",\"digest\":\"介绍了天文学的基本概念、天体的演化、星系的结构等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2023/03/06/14/27/man-7833615_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"华东师范大学数学系\",\"bookId\":29,\"bookName\":\"《数学分析》\",\"digest\":\"是数学专业的基础课程教材，主要内容包括极限、导数、积分等。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/29/13/46/book-1869969_1280.jpg\",\"subject\":\"理学\"},{\"author\":\"哈里德\",\"bookId\":30,\"bookName\":\"《物理学》\",\"digest\":\"涵盖了经典物理学和现代物理学的主要内容，是一本经典的物理学教材。\",\"picture\":\"https://cdn.pixabay.com/photo/2015/11/19/21/11/atlas-1052011_1280.jpg\",\"subject\":\"理学\"}]', '2025-04-02 15:52:16');
INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (256, NULL, NULL, 2, '[\"法学\"]', '[{\"author\":\"孟德斯鸠\",\"bookId\":11,\"bookName\":\"《论法的精神》\",\"digest\":\"探究法与政制关联，提出三权分立之学说\",\"picture\":\"https://cdn.pixabay.com/photo/2023/10/05/11/57/book-8295812_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"博登海默\",\"bookId\":12,\"bookName\":\"《法理学：法律哲学与法律方法》\",\"digest\":\"全面阐释法理问题，详述法律哲学诸流派\",\"picture\":\"https://cdn.pixabay.com/photo/2018/10/04/14/22/reading-3723751_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"张千帆\",\"bookId\":13,\"bookName\":\"《宪法学》\",\"digest\":\"系统介绍宪法原理，讲述中国宪法发展史\",\"picture\":\"https://cdn.pixabay.com/photo/2022/11/08/06/05/read-7577787_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"王利明\",\"bookId\":14,\"bookName\":\"《民法总则研究》\",\"digest\":\"深入研究民法总则，探讨各项制度与规则\",\"picture\":\"https://cdn.pixabay.com/photo/2015/12/05/08/25/fantasy-1077863_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"张明楷\",\"bookId\":15,\"bookName\":\"《刑法学》\",\"digest\":\"详讲刑法基本理论，涵盖犯罪刑罚诸内容\",\"picture\":\"https://cdn.pixabay.com/photo/2022/11/03/13/07/book-7567437_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"姜明安\",\"bookId\":16,\"bookName\":\"《行政法与行政诉讼法》\",\"digest\":\"介绍行政法之概念，涉及诉讼行为诸知识\",\"picture\":\"https://cdn.pixabay.com/photo/2023/01/15/16/20/library-7720589_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"崔建远\",\"bookId\":17,\"bookName\":\"《合同法》\",\"digest\":\"围绕合同订立履行，详细阐述变更转让事\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/29/07/21/book-1868068_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"吴汉东\",\"bookId\":18,\"bookName\":\"《知识产权法》\",\"digest\":\"阐述知识法理原则，涵盖著作专利商标权\",\"picture\":\"https://cdn.pixabay.com/photo/2020/05/15/13/28/reading-5173530_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"王铁崖\",\"bookId\":19,\"bookName\":\"《国际法》\",\"digest\":\"介绍国际基本概念，包含主体领土海洋法\",\"picture\":\"https://cdn.pixabay.com/photo/2016/10/25/15/55/book-1769228_1280.jpg\",\"subject\":\"法学\"},{\"author\":\"何家弘\",\"bookId\":20,\"bookName\":\"《证据法学》\",\"digest\":\"系统研究证据法理，明晰规则责任诸问题\",\"picture\":\"https://cdn.pixabay.com/photo/2016/08/24/16/20/books-1617327_1280.jpg\",\"subject\":\"法学\"}]', '2025-04-02 15:52:21');
