INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (258, NULL, NULL, 2, '[\"文学\"]', '[{\"author\":\"加西亚·马尔克斯\",\"bookId\":1,\"bookName\":\"《百年孤独》\",\"digest\":\"魔幻巨著叙布恩迪亚七代传奇家族兴衰\",\"picture\":\"https://cdn.pixabay.com/photo/2014/09/05/18/32/old-books-436498_1280.jpg\",\"subject\":\"文学\"},{\"author\":\"鲁迅\",\"bookId\":2,\"bookName\":\"《呐喊》\",\"digest\":\"收录短篇揭18 - 22年社会矛盾振聋发聩\",\"picture\":\"https://cdn.pixabay.com/photo/2016/03/27/19/32/book-1283865_1280.jpg\",\"subject\":\"文学\"},{\"author\":\"莎士比亚\",\"bookId\":3,\"bookName\":\"《哈姆雷特》\",\"digest\":\"哈姆雷特为父复仇，探讨人性道德之题\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/29/03/09/beach-1866992_1280.jpg\",\"subject\":\"文学\"},{\"author\":\"欧内斯特·海明威\",\"bookId\":4,\"bookName\":\"《老人与海》\",\"digest\":\"老渔夫勇斗马林鱼，展现坚韧不拔之精神\",\"picture\":\"https://cdn.pixabay.com/photo/2015/12/04/09/13/leaves-1076307_1280.jpg\",\"subject\":\"文学\"},{\"author\":\"夏洛蒂·勃朗特\",\"bookId\":5,\"bookName\":\"《简·爱》\",\"digest\":\"孤女简·爱寻自由尊严，终获幸福人生之旅\",\"picture\":\"https://cdn.pixabay.com/photo/2015/11/19/21/14/glasses-1052023_1280.jpg\",\"subject\":\"文学\"},{\"author\":\"维克多·雨果\",\"bookId\":6,\"bookName\":\"《巴黎圣母院》\",\"digest\":\"15 世纪法国奇事，揭露专制宗教虚伪黑暗\",\"picture\":\"https://cdn.pixabay.com/photo/2014/08/16/18/17/book-419589_1280.jpg\",\"subject\":\"文学\"},{\"author\":\"玛格丽特·米切尔\",\"bookId\":7,\"bookName\":\"《飘》\",\"digest\":\"南北战争背景下，斯嘉丽乱世成长之历程\",\"picture\":\"https://cdn.pixabay.com/photo/2015/07/27/20/16/book-863418_1280.jpg\",\"subject\":\"文学\"},{\"author\":\"罗贯中\",\"bookId\":8,\"bookName\":\"《三国演义》\",\"digest\":\"东汉末年至西晋，三国政治军事斗争风云\",\"picture\":\"https://cdn.pixabay.com/photo/2017/02/26/21/39/rose-2101475_1280.jpg\",\"subject\":\"文学\"},{\"author\":\"曹雪芹\",\"bookId\":9,\"bookName\":\"《红楼梦》\",\"digest\":\"四大家族兴衰史，宝黛钗爱情悲剧之写照\",\"picture\":\"https://cdn.pixabay.com/photo/2015/06/02/12/59/book-794978_1280.jpg\",\"subject\":\"文学\"},{\"author\":\"老舍\",\"bookId\":10,\"bookName\":\"《骆驼祥子》\",\"digest\":\"20 年代祥子三起三落，揭示社会黑暗之象\",\"picture\":\"https://cdn.pixabay.com/photo/2018/07/01/20/01/music-3510326_1280.jpg\",\"subject\":\"文学\"}]', '2025-04-02 15:54:42');
