INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (261, NULL, NULL, 2, '[\"工学\"]', '[{\"author\":\"唐纳德·克努特\",\"bookId\":31,\"bookName\":\"《计算机程序设计艺术》\",\"digest\":\"计算机科学领域的经典著作，涵盖了算法分析、数据结构等多个方面。\",\"picture\":\"https://cdn.pixabay.com/photo/2019/05/14/21/50/storytelling-4203628_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"机械设计手册编委会\",\"bookId\":32,\"bookName\":\"《机械设计手册》\",\"digest\":\"提供了机械设计的各种标准、规范和设计方法。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/29/02/56/blonde-1866951_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"邱关源\",\"bookId\":33,\"bookName\":\"《电路原理》\",\"digest\":\"介绍了电路的基本定律、电路分析方法、正弦稳态电路等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2017/03/23/12/23/vintage-2168174_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"胡寿松\",\"bookId\":34,\"bookName\":\"《自动控制原理》\",\"digest\":\"阐述了自动控制系统的基本原理、分析方法和设计方法。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/06/01/06/26/open-book-1428428_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"孙伟\",\"bookId\":35,\"bookName\":\"《土木工程材料》\",\"digest\":\"介绍了土木工程中常用的材料，如水泥、钢材、混凝土等的性能和应用。\",\"picture\":\"https://cdn.pixabay.com/photo/2022/07/08/10/37/books-7309019_1280.png\",\"subject\":\"工学\"},{\"author\":\"樊昌信\",\"bookId\":36,\"bookName\":\"《通信原理》\",\"digest\":\"讲述了通信系统的基本原理、模拟通信和数字通信等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2019/03/01/14/54/girl-4028008_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"谭天恩\",\"bookId\":37,\"bookName\":\"《化工原理》\",\"digest\":\"介绍了化工生产中的基本单元操作，如流体输送、传热、蒸馏等的原理和计算方法。\",\"picture\":\"https://cdn.pixabay.com/photo/2019/11/04/10/15/book-4600757_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"张海藩\",\"bookId\":38,\"bookName\":\"《软件工程》\",\"digest\":\"系统介绍了软件工程的基本概念、方法和技术，包括软件开发过程、软件项目管理等。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/18/16/56/book-1835799_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"何仰赞\",\"bookId\":39,\"bookName\":\"《电力系统分析》\",\"digest\":\"主要内容包括电力系统的潮流计算、短路计算、电力系统稳定性分析等。\",\"picture\":\"https://cdn.pixabay.com/photo/2021/12/12/09/41/woman-6864640_1280.jpg\",\"subject\":\"工学\"},{\"author\":\"王建国\",\"bookId\":40,\"bookName\":\"《建筑设计基础》\",\"digest\":\"介绍了建筑设计的基本原理、方法和程序，培养建筑设计的基本能力。\",\"picture\":\"https://cdn.pixabay.com/photo/2019/05/04/14/22/woman-4178187_1280.jpg\",\"subject\":\"工学\"}]', '2025-04-02 15:54:47');
INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (262, NULL, NULL, 2, '[\"自然科学\"]', '[{\"author\":\"查尔斯·达尔文\",\"bookId\":41,\"bookName\":\"《物种起源》\",\"digest\":\"提出了生物进化的理论，对生物学的发展产生了深远影响。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/05/28/07/05/book-1421097_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"让 - 亨利·卡西米尔·法布尔\",\"bookId\":42,\"bookName\":\"《昆虫记》\",\"digest\":\"生动记录了昆虫的生活习性和特征，是一部优秀的科普作品。\",\"picture\":\"https://cdn.pixabay.com/photo/2022/01/22/16/54/book-6957870_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"比尔·布莱森\",\"bookId\":43,\"bookName\":\"《万物简史》\",\"digest\":\"以通俗易懂的语言介绍了宇宙、地球、生命的起源和发展等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2014/06/28/12/35/books-378903_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"斯蒂芬·霍金\",\"bookId\":44,\"bookName\":\"《果壳中的宇宙》\",\"digest\":\"继续探讨了宇宙的奥秘，包括宇宙的起源、黑洞、时间旅行等问题。\",\"picture\":\"https://cdn.pixabay.com/photo/2020/05/15/19/37/book-5174879_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"布鲁斯·阿尔伯茨\",\"bookId\":45,\"bookName\":\"《细胞》\",\"digest\":\"全面介绍了细胞的结构、功能、代谢等方面的知识。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/04/30/13/12/sutterlin-1362879_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"李扬汉\",\"bookId\":46,\"bookName\":\"《植物学》\",\"digest\":\"介绍了植物的形态、结构、分类、生理等方面的知识。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/29/11/25/bible-1869164_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"刘凌云\",\"bookId\":47,\"bookName\":\"《动物学》\",\"digest\":\"系统介绍了动物的分类、形态、生理、生态等方面的知识。\",\"picture\":\"https://cdn.pixabay.com/photo/2019/11/02/20/50/camera-4597415_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"彼得·维恩\",\"bookId\":48,\"bookName\":\"《海洋生物学》\",\"digest\":\"讲述了海洋生物的种类、生态、进化等方面的知识。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/12/30/19/33/children-1941336_1280.png\",\"subject\":\"自然科学\"},{\"author\":\"曹伯勋\",\"bookId\":49,\"bookName\":\"《地质学与地貌学》\",\"digest\":\"介绍了地球的地质构造、地质作用、地貌形成等方面的知识。\",\"picture\":\"https://cdn.pixabay.com/photo/2017/12/17/21/44/drink-3025022_1280.jpg\",\"subject\":\"自然科学\"},{\"author\":\"周淑贞\",\"bookId\":50,\"bookName\":\"《气象学与气候学》\",\"digest\":\"介绍了气象学和气候学的基本概念、大气的组成和结构、天气系统和气候类型等内容。\",\"picture\":\"https://cdn.pixabay.com/photo/2016/11/23/17/31/man-1853961_1280.jpg\",\"subject\":\"自然科学\"}]', '2025-04-02 15:54:49');
INSERT INTO `sys_log` (`id`, `token`, `username`, `content`, `param`, `result`, `create_time`) VALUES (263, NULL, NULL, 2, '[\"历史学\"]', '[{\"author\":\"司马迁\",\"bookId\":51,\"bookName\":\"《史记》\",\"digest\":\"中国第一部纪传体通史，记载了从上古传说到汉武帝时期的历史。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=史记\",\"subject\":\"历史学\"},{\"author\":\"斯塔夫里阿诺斯\",\"bookId\":52,\"bookName\":\"《全球通史：从史前史到21世纪》\",\"digest\":\"以全球的视角讲述了人类历史的发展进程。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=全球通史\",\"subject\":\"历史学\"},{\"author\":\"司马光\",\"bookId\":53,\"bookName\":\"《资治通鉴》\",\"digest\":\"编年体通史巨著，记录了公元前403年到公元959年共16朝1362年的历史。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=资治通鉴\",\"subject\":\"历史学\"},{\"author\":\"翦伯赞\",\"bookId\":54,\"bookName\":\"《中国史纲要》\",\"digest\":\"是一部简明扼要的中国通史教材，涵盖了从原始社会到近代的历史。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=中国史纲要\",\"subject\":\"历史学\"},{\"author\":\"赫伯特·乔治·韦尔斯\",\"bookId\":55,\"bookName\":\"《世界史纲》\",\"digest\":\"以通俗的语言叙述了从宇宙起源到20世纪初的世界历史。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=世界史纲\",\"subject\":\"历史学\"},{\"author\":\"陈寅恪\",\"bookId\":56,\"bookName\":\"《隋唐制度渊源略论稿》\",\"digest\":\"探讨了隋唐制度的渊源和演变，具有重要的学术价值。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=隋唐制度渊源略论稿\",\"subject\":\"历史学\"},{\"author\":\"黄仁宇\",\"bookId\":57,\"bookName\":\"《万历十五年》\",\"digest\":\"以明朝万历十五年为切入点，分析了明朝社会的政治、经济、文化等方面的问题。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=万历十五年\",\"subject\":\"历史学\"},{\"author\":\"贾雷德·戴蒙德\",\"bookId\":58,\"bookName\":\"《枪炮、病菌与钢铁：人类社会的命运》\",\"digest\":\"试图讲述“最近13000年来所有人的简短历史”，并解释为何欧亚文明最终可以存活下来并战胜其他文明。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=枪炮、病菌与钢铁\",\"subject\":\"历史学\"},{\"author\":\"裴骃、司马贞、张守节\",\"bookId\":59,\"bookName\":\"《史记三家注》\",\"digest\":\"是《史记》的重要注释本，对理解《史记》具有重要的参考价值。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=史记三家注\",\"subject\":\"历史学\"},{\"author\":\"钱穆\",\"bookId\":60,\"bookName\":\"《国史大纲》\",\"digest\":\"是中国通史的经典著作之一，强调了中国历史的连续性和独特性。\",\"picture\":\"https://dummyimage.com/200x300/000/fff&text=国史大纲\",\"subject\":\"历史学\"}]', '2025-04-02 15:54:50');
